#!/usr/bin/env python3
"""Lane thinorbit (S93).  The group generated by the unimodular port-chain blocks: 2-adic image and short words.

 (1) image mod 2, 4, 8 of the semigroup generated by the unimodular blocks (order <= 4: 8 matrices; order <= 6: 46)
     against the full preimage of the mod-2 image (size 2^(8(k-1)) times the mod-2 order);
 (2) search of the words of length <= 4 in the 8 generators and their inverses for unipotent elements other than
     the identity (an elementary matrix inside the generated group would point to finite index in SL_3(Z)).
"""
import itertools
import numpy as np
import sympy as sp
from group_probe import closure_mod_p, load

for name in ("sub_k4_uni.txt", "sub_k6_uni.txt"):
    gens = load(name)
    sizes = {}
    for q in (2, 4, 8):
        el = closure_mod_p(gens, q, cap=10 ** 9)
        sizes[q] = len(el)
    print(f"{name}: {len(gens)} unimodular generators; image mod 2: {sizes[2]}, mod 4: {sizes[4]} (full preimage of the mod-2 image: "
          f"{sizes[2] * 2 ** 8}), mod 8: {sizes[8]} (full preimage: {sizes[2] * 2 ** 16})")
gens = load("sub_k4_uni.txt")
G = [sp.Matrix(3, 3, [int(x) for x in g.reshape(-1)]) for g in gens]
letters = [np.array(g.tolist(), dtype=object) for g in G] + [np.array(g.inv().tolist(), dtype=object) for g in G]
I3 = np.array(sp.eye(3).tolist(), dtype=object)
found = []
seen = set()
front = [I3]
seen.add(tuple(I3.reshape(-1)))
total = 0
for length in range(1, 5):
    new = []
    for M in front:
        for L in letters:
            P = M.dot(L)
            key = tuple(P.reshape(-1))
            if key in seen:
                continue
            seen.add(key)
            new.append(P)
            total += 1
            tr = P[0, 0] + P[1, 1] + P[2, 2]
            if tr == 3:
                m2 = P[0, 0] * P[1, 1] - P[0, 1] * P[1, 0] + P[0, 0] * P[2, 2] - P[0, 2] * P[2, 0] + P[1, 1] * P[2, 2] - P[1, 2] * P[2, 1]
                if m2 == 3:
                    found.append((length, key))
    front = new
    print(f"words of length {length}: {len(new)} new group elements (total {total}); unipotent non-identity elements found so far: {len(found)}")
for f in found[:10]:
    print("   unipotent:", f)
